//! Parity: every `meerschaum.config.paths` name derives the same path as Python
//! (`fixtures/paths.json`, generated by `fixtures/gen_paths.py`).

mod common;

use std::path::PathBuf;

use meerschaum_core::Value;
use meerschaum_core::config::paths::{Paths, posix};

#[test]
fn paths_match_python() {
    let fixture = common::load_fixture("paths.json");
    for (case, data) in fixture.as_map().unwrap() {
        let tmp = tempfile::tempdir().unwrap();
        let tmp_path = tmp.path().canonicalize().unwrap();
        let tmp_str = posix(&tmp_path);
        std::fs::create_dir_all(tmp_path.join("root")).unwrap();
        std::fs::create_dir_all(tmp_path.join("cfg")).unwrap();
        std::fs::create_dir_all(tmp_path.join("plugins")).unwrap();

        let mut env: Vec<(String, String)> = vec![
            ("MRSM_ROOT_DIR".into(), format!("{tmp_str}/root")),
            ("MRSM_PLUGINS_DIR".into(), format!("{tmp_str}/plugins")),
        ];
        for (k, v) in data.get("env").and_then(Value::as_map).unwrap() {
            let v = v.as_str().unwrap().replace("{TMP}", &tmp_str);
            env.retain(|(ek, _)| ek != k);
            env.push((k.clone(), v));
        }
        let lookup = |key: &str| env.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone());
        let paths =
            Paths::from_env(&lookup, &tmp_path, false, Some(PathBuf::from("{PACKAGE}"))).unwrap();

        let expected = data.get("paths").and_then(Value::as_map).unwrap();
        let names = Paths::names();
        assert_eq!(
            names.len() + 2,
            expected.len(),
            "every Python path name is ported ({case})"
        );
        for name in names {
            let actual = paths
                .get(name)
                .unwrap_or_else(|| panic!("{case}: missing {name}"))
                .as_posix()
                .replace(&tmp_str, "{TMP}");
            assert_eq!(
                Some(actual.as_str()),
                expected.get(name).and_then(Value::as_str),
                "{case}: {name}"
            );
        }
        let plugins: Vec<String> = paths
            .plugins_dirs
            .iter()
            .map(|p| posix(p).replace(&tmp_str, "{TMP}"))
            .collect();
        let expected_plugins: Vec<String> = expected
            .get("PLUGINS_DIR_PATHS")
            .and_then(Value::as_list)
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect();
        assert_eq!(plugins, expected_plugins, "{case}: PLUGINS_DIR_PATHS");
        assert_eq!(
            Some(
                posix(&paths.dot_config_dir)
                    .replace(&tmp_str, "{TMP}")
                    .as_str()
            ),
            expected.get("DOT_CONFIG_DIR_PATH").and_then(Value::as_str),
            "{case}: DOT_CONFIG_DIR_PATH"
        );
    }
}
